mapper.select:
SELECT l.*, a.name_zh AS app_name, p.name AS project_name FROM app_project_links l LEFT JOIN ui_apps a ON a.id = l.app_id LEFT JOIN api_projects p ON p.code = l.project_code
AND l.app_id = #{appId} AND l.project_code = #{projectCode}
ORDER BY l.app_id ASC, l.platform ASC, l.project_code ASC

mapper.update:
UPDATE app_project_links
SET platform = #{platform},
    relation = #{relation},
    note     = #{note}
WHERE app_id = #{appId} AND project_code = #{projectCode}

mapper.select:
SELECT l.project_code AS projectCode, l.app_id AS appId, l.platform AS platform, (SELECT COUNT(*) FROM ui_elements e WHERE e.app_id = l.app_id AND (l.platform IS NULL OR UPPER(IFNULL(e.platform, '')) = l.platform)) AS elementCount, (SELECT COUNT(*) FROM ui_flows f WHERE f.app_id = l.app_id) AS flowCount, (SELECT COUNT(*) FROM ui_pages g WHERE g.app_id = l.app_id) AS pageCount FROM app_project_links l
AND l.project_code = #{projectCode}
ORDER BY l.project_code ASC
